import{_ as l,r as t,o as i,c as r,e,a as n,s as p,d as a}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Контроллеры - October CMS - 3.x","titleTemplate":false,"description":"Создавайте страницы, реализующие различные функции, такие как формы и списки.","frontmatter":{"subtitle":"Создавайте страницы, реализующие различные функции, такие как формы и списки."},"headers":[{"level":3,"title":"Определение класса","slug":"определение-класса","link":"#определение-класса","children":[]},{"level":3,"title":"Свойства контроллера","slug":"своиства-контроллера","link":"#своиства-контроллера","children":[]},{"level":2,"title":"Логика инициализации","slug":"логика-инициализации","link":"#логика-инициализации","children":[]},{"level":2,"title":"Действия, представления и маршрутизация","slug":"деиствия-представления-и-маршрутизация","link":"#деиствия-представления-и-маршрутизация","children":[]},{"level":2,"title":"Передача данных в представления","slug":"передача-данных-в-представления","link":"#передача-данных-в-представления","children":[]},{"level":2,"title":"Установка контекста навигации","slug":"установка-контекста-навигации","link":"#установка-контекста-навигации","children":[]},{"level":2,"title":"Переопределение ответа","slug":"переопределение-ответа","link":"#переопределение-ответа","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/system/controllers.md","filePath":"3.x/ru/extend/system/controllers.md"}'),u={name:"3.x/ru/extend/system/controllers.md"};function d(k,s,g,h,m,v){const o=t("pre-heading"),c=t("post-heading");return i(),r("div",null,[e(o),s[0]||(s[0]=n("h1",null,"Контроллеры",-1)),e(c),s[1]||(s[1]=p(`<p>Панель управления October CMS реализует паттерн Model-View-Controller (MVC). В этой статье описывается, как разрабатывать контроллеры панели управления и как настраивать поведения контроллеров.</p><p>Каждый контроллер представлен PHP-скриптом, который находится в поддиректории <strong>/controllers</strong> директории плагина. Представления контроллера — это файлы <code>.php</code>, расположенные в директории представлений контроллера. Имя директории представлений совпадает с именем класса контроллера в нижнем регистре. Директория представлений также может содержать файлы конфигурации контроллера. Пример структуры директории контроллера:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>controllers</code>
|           |   ├── users  <em>← Директория представлений</em>
|           |   |   ├── config_form.yaml  <em>← Файл конфигурации</em>
|           |   |   ├── _partial.php  <em>← Файл частичного представления</em>
|           |   |   └── index.php  <em>← Файл представления</em>
|           |   └── Users.php  <em>← Класс контроллера</em>
|           └── Plugin.php</p>
</code></pre>`,3)),s[2]||(s[2]=n("div",{class:"custom-block tip"},[n("p",null,[a("Практический пример использования контроллеров панели управления можно найти в "),n("a",{href:"https://octobercms.com/support/article/ob-19",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("серии уроков Beyond Behaviors"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(".")])],-1)),s[3]||(s[3]=p(`<h3 id="определение-класса"><a href="#определение-класса" class="header-anchor">#</a> Определение класса</h3><p>Команда <code>create:controller</code> генерирует контроллер, файлы конфигурации и представлений. Первый аргумент указывает имя автора и плагина. Второй аргумент указывает имя класса контроллера.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts
</code></pre></div><p>Классы контроллеров должны наследовать класс <code>Backend\\Classes\\Controller</code>. Как и любой другой класс плагина, контроллеры должны принадлежать <a href="./../system/plugins.html">пространству имён плагина</a>. Самое базовое представление контроллера, используемого внутри плагина, выглядит так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span>    <span class="token comment">// ← Action method</span>
    <span class="token punctuation">{</span>

    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Обычно каждый контроллер реализует функциональность для работы с одним типом данных — например, записями блога или категориями. Все описанные ниже поведения панели управления предполагают эту конвенцию.</p><h3 id="своиства-контроллера"><a href="#своиства-контроллера" class="header-anchor">#</a> Свойства контроллера</h3><p>Базовый класс контроллера панели управления определяет ряд свойств, позволяющих настраивать внешний вид страницы и управлять безопасностью страницы:</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>$fatalError</strong></td><td>позволяет сохранить фатальное исключение, сгенерированное в методе действия, для отображения в представлении.</td></tr><tr><td><strong>$user</strong></td><td>содержит ссылку на объект пользователя панели управления.</td></tr><tr><td><strong>$suppressView</strong></td><td>позволяет предотвратить отображение представления. Может быть обновлено в методе действия или в конструкторе контроллера.</td></tr><tr><td><strong>$params</strong></td><td>массив маршрутизированных параметров.</td></tr><tr><td><strong>$action</strong></td><td>имя метода действия, выполняемого в текущем запросе.</td></tr><tr><td><strong>$publicActions</strong></td><td>определяет массив действий, доступных без аутентификации пользователя панели управления. Может быть переопределено в определении класса.</td></tr><tr><td><strong>$requiredPermissions</strong></td><td>разрешения, необходимые для просмотра этой страницы. Может быть задано в определении класса или в конструкторе контроллера. Подробнее см. <a href="./../backend/users.html">пользователи и разрешения</a>.</td></tr><tr><td><strong>$pageTitle</strong></td><td>задаёт заголовок страницы. Может быть задано в методе действия.</td></tr><tr><td><strong>$bodyClass</strong></td><td>свойство CSS-класса body, используемое для настройки макета. Может быть задано в конструкторе контроллера или методе действия.</td></tr><tr><td><strong>$guarded</strong></td><td>специфические для контроллера методы, которые не могут быть вызваны как действия. Может быть расширено в конструкторе контроллера.</td></tr><tr><td><strong>$layout</strong></td><td>указывает пользовательский макет для <a href="./../system/views.html">представлений контроллера</a>.</td></tr></tbody></table></div><h2 id="логика-инициализации"><a href="#логика-инициализации" class="header-anchor">#</a> Логика инициализации</h2><p>Контроллеры могут выполнять логику инициализации в нативном методе <code>__construct</code>.</p><div class="custom-block warning"><p>Логика внутри конструктора не защищена и не должна обрабатывать конфиденциальную логику.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div></div><p>Метод <code>beforeDisplay</code> вызывается после проверки разрешений, и большая часть логики должна быть размещена здесь. Это включает инициализацию виджетов и других общих компонентов.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeDisplay</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Initialize widgets, handle file uploads, etc.</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="деиствия-представления-и-маршрутизация"><a href="#деиствия-представления-и-маршрутизация" class="header-anchor">#</a> Действия, представления и маршрутизация</h2><p>Публичные методы контроллера, называемые <strong>действиями</strong>, связаны с <strong>файлами представлений</strong>, которые представляют страницу, соответствующую действию. Файлы представлений панели управления используют синтаксис PHP. Пример содержимого файла представления <strong>index.php</strong>, соответствующего методу действия <code>index</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello World<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>URL этой страницы составляется из имени автора, имени плагина, имени контроллера и имени действия.</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[author name]/[plugin name]/[controller name]/[action name]
</code></pre></div><p>Например, определение класса, использованное в начале этой статьи, доступно по следующему URL.</p><div class="language-text extra-class"><pre class="language-text"><code>https://example.tld/admin/acme/blog/users/index
</code></pre></div><p>Если <a href="./plugins.html">плагин зарегистрирован</a> с <strong>hint</strong> в методе <code>pluginDetails</code>, становится доступна более короткая структура URL, что полезно для маскировки имени автора в URL.</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[plugin hint]/[controller name]/[action name]
</code></pre></div><h2 id="передача-данных-в-представления"><a href="#передача-данных-в-представления" class="header-anchor">#</a> Передача данных в представления</h2><p>Используйте свойство контроллера <code>$vars</code> для передачи любых данных непосредственно в представление:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Переменные, переданные через свойство <code>$vars</code>, теперь доступны непосредственно в вашем представлении:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The variable value is <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$myVariable</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="установка-контекста-навигации"><a href="#установка-контекста-навигации" class="header-anchor">#</a> Установка контекста навигации</h2><p>Плагины могут регистрировать меню и подменю панели управления в <a href="./../backend/navigation.html">файле регистрации плагина</a>. Контекст навигации определяет, какое меню и подменю панели управления активны для текущей страницы. Вы можете установить контекст навигации с помощью класса <code>BackendMenu</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Первый параметр указывает имена автора и плагина. Второй параметр задаёт код меню. Необязательный третий параметр указывает код подменю. Обычно <code>BackendMenu::setContext</code> вызывается в конструкторе контроллера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span> <span class="token punctuation">{</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете задать заголовок страницы панели управления через свойство <code>$pageTitle</code> класса контроллера (обратите внимание, что поведения формы и списка могут делать это за вас):</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">pageTitle</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Blog Categories&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="переопределение-ответа"><a href="#переопределение-ответа" class="header-anchor">#</a> Переопределение ответа</h2><p>Вы можете переопределять ответы в контроллерах панели управления как механизм для внесения изменений в ответ HTTP-запроса. Например, вы можете захотеть указать HTTP-заголовок для определённых действий контроллера или перенаправить пользователей, если они не соответствуют определённым критериям.</p><p>Переопределение ответа особенно полезно при расширении других контроллеров. Однако вы также можете использовать эти методы локально.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите проверить маршрутизированное действие или параметры, они доступны через методы контроллера <code>getAction</code> и <code>getParams</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;index&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only do it for the index action</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getParams</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only if first parameter exists</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для добавления заголовка к ответу используйте метод <code>setResponseHeader</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для изменения кода состояния ответа используйте метод <code>setStatusCode</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для полного переопределения ответа вызовите метод <code>setResponse</code> — он принудительно установит ответ независимо от того, что происходит в жизненном цикле страницы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Page Not Found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете передать объект <code>Response</code> в этот метод.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Подробнее о создании ответов см. в статье <a href="./../services/response-view.html">Представления и ответы</a>.</p><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../services/response-view.html">Представления и ответы</a></li></ul></div>`,52))])}const b=l(u,[["render",d]]);export{x as __pageData,b as default};
